/**
 * Filters an array to include only elements that appear exactly once in the original array.
 * @param {number[]} arr - The input array of numbers.
 * @returns {number[]} A new array containing elements that appear exactly once.
 */
function findUniqueElements(arr) {
    const counts = new Map();
    // Count frequency of each element
    for (const num of arr) {
        counts.set(num, (counts.get(num) || 0) + 1);
    }
    // Return elements that appear exactly once
    return arr.filter(num => counts.get(num) === 1);
}
